class Range {
  constructor(a, b) { this.a = a; this.b = b; }
  [Symbol.iterator]() {
    let i = this.a; const end = this.b;
    return {
      next: () => (i <= end ? { value: i++, done: false } : { value: undefined, done: true }),
      return: () => { console.log('cleanup'); return { done: true }; },
    };
  }
}
